const DAILY_20261003=[
{id:"jota",n:"Jota (Slovenian Bean and Sauerkraut Stew)",c:"Slovenia",f:"🇸🇮",m:55,x:["sauerkraut","kidney beans","potato","pork","garlic","bay leaf"],s:["Rinse the sauerkraut briefly if it is very salty, then drain it.","Simmer diced potato with garlic and bay leaf until nearly tender.","Add sauerkraut, cooked kidney beans, and small pieces of pork.","Cook gently until thick and well blended, then remove the bay leaf and season."],co:"#9a7048",source:"https://www.tasteslovenia.si/en/typical-dishes",license:LICENSE,sourceNote:NOTE},
{id:"struklji",n:"Štruklji (Slovenian Curd-Cheese Rolled Dumplings)",c:"Slovenia",f:"🇸🇮",m:60,x:["flour","cheese","egg","sour cream","butter","breadcrumbs"],s:["Mix flour, egg, and water into a supple dough and rest it covered.","Roll the dough thin and spread it with cheese mixed with sour cream.","Roll tightly, wrap securely, and simmer until the dough is cooked through.","Slice the roll and finish with breadcrumbs toasted in butter."],co:"#d5b36a",source:"https://www.visitljubljana.com/en/visitors/in-focus/stories/when-trying-local-and-slovenian-food-struklji-are-a-must",license:LICENSE,sourceNote:NOTE},
{id:"adjarian-khachapuri",n:"Adjaruli Khachapuri (Georgian Boat-Shaped Cheese Bread)",c:"Georgia",f:"🇬🇪",m:75,x:["flour","yeast","milk","cheese","egg","butter"],s:["Mix flour, yeast, warm milk, and salt, then knead and let the dough rise.","Shape the dough into a boat with raised edges and fill it with cheese.","Bake until the crust is golden and the cheese is bubbling.","Add the egg and butter near the end, baking just until the white sets lightly."],co:"#d9a441",source:"https://georgia.travel/rediscovering-khachapuri-georgias-must-try-classic",license:LICENSE,sourceNote:NOTE},
{id:"lobio",n:"Lobio (Georgian Kidney Bean and Walnut Stew)",c:"Georgia",f:"🇬🇪",m:45,x:["kidney beans","walnut","onion","garlic","cilantro","pomegranate molasses"],s:["Cook the onion slowly until soft, then add garlic.","Add kidney beans with a little cooking liquid and mash some of them.","Stir in crushed walnuts, cilantro, and a small amount of pomegranate molasses.","Simmer until thick, then adjust salt and acidity before serving."],co:"#8c3f35",source:"https://georgia.travel/top-eleven-georgian-food",license:LICENSE,sourceNote:NOTE},
{id:"ceebu-jen",n:"Ceebu Jën (Senegalese Fish and Vegetable Rice)",c:"Senegal",f:"🇸🇳",m:90,x:["fish","rice","tomato","cabbage","carrot","cassava"],s:["Season the fish and brown it lightly in a wide pot.","Cook tomato with aromatics, then add water and the cabbage, carrot, and cassava.","Remove the tender fish and vegetables, reserving the seasoned cooking liquid.","Cook the rice in that liquid until absorbed, then serve with the fish and vegetables."],co:"#c74c32",source:"https://ich.unesco.org/en/RL/ceebu-jen-a-culinary-art-of-senegal-01748",license:LICENSE,sourceNote:NOTE},
{id:"poulet-yassa",n:"Poulet Yassa (Senegalese Lemon-Onion Chicken)",c:"Senegal",f:"🇸🇳",m:65,x:["chicken","onion","lemon","mustard","rice","olive oil"],s:["Marinate the chicken with sliced onion, lemon, mustard, salt, and pepper.","Lift out the chicken and brown it in a lightly oiled pan.","Cook the marinated onions slowly, then add the marinade and return the chicken.","Simmer until tender and serve the lemon-onion sauce over cooked rice."],co:"#d4a23c",source:"https://www.britannica.com/place/Senegal/Cultural-life",license:LICENSE,sourceNote:NOTE},
{id:"beef-rendang",n:"Rendang Daging (Indonesian Coconut-Braised Beef)",c:"Indonesia",f:"🇮🇩",m:150,x:["beef","coconut milk","onion","garlic","ginger","curry powder"],s:["Blend onion, garlic, ginger, and spices into a fragrant paste.","Cook the paste gently, then add beef and turn it until evenly coated.","Pour in coconut milk and simmer uncovered over low heat.","Stir more often as the liquid reduces, cooking until the beef is tender and the sauce clings darkly."],co:"#8e4032",source:"https://www.indonesia.travel/gb/en/travel-ideas/don-t-leave-indonesia-before-you-get-a-taste-of-these-12-favorite-local-foods/",license:LICENSE,sourceNote:NOTE},
{id:"satay-ayam",n:"Sate Ayam (Indonesian Chicken Satay)",c:"Indonesia",f:"🇮🇩",m:40,x:["chicken","soy sauce","peanuts","lime","garlic","sugar"],s:["Cut the chicken into small even pieces and marinate with soy sauce, garlic, lime, and sugar.","Thread the chicken onto skewers without packing the pieces too tightly.","Grill or sear over high heat, turning until browned and fully cooked.","Crush the peanuts into a warm sauce and serve it with the hot skewers."],co:"#c77a32",source:"https://www.indonesia.travel/gb/en/travel-ideas/don-t-leave-indonesia-before-you-get-a-taste-of-these-12-favorite-local-foods/",license:LICENSE,sourceNote:NOTE},
{id:"pelkie-zirni-ar-speki",n:"Pelēkie Zirņi ar Speķi (Latvian Grey Peas with Bacon)",c:"Latvia",f:"🇱🇻",m:70,x:["dried peas","bacon","onion","butter","sour cream","rye bread"],s:["Soak the dried peas ahead of time, then simmer them until tender but intact.","Dice the bacon and cook it until the fat renders and the edges brown.","Add onion and cook until soft, then fold in the drained peas and butter.","Serve hot with sour cream and rye bread."],co:"#8d5f46",source:"https://www.latvia.travel/en/flavours-latvia",license:LICENSE,sourceNote:NOTE},
{id:"sklandrausis",n:"Sklandrausis (Latvian Rye, Potato and Carrot Tart)",c:"Latvia",f:"🇱🇻",m:70,x:["rye flour","potato","carrot","sour cream","egg","butter"],s:["Mix rye flour with warm water and butter, then press it into small tart shells with raised rims.","Spread a smooth potato layer over the base.","Cover with sweetened carrot mash mixed with egg and sour cream.","Bake until the rye crust is firm and the carrot surface is lightly browned."],co:"#c77b3d",source:"https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A52021XC0505%2802%29",license:LICENSE,sourceNote:NOTE}
];
