window.RECIPE_I18N=window.RECIPE_I18N||{};
Object.assign(window.RECIPE_I18N,{
"jota":{ko:["요타(슬로베니아식 콩·사워크라우트 스튜)",["사워크라우트가 매우 짜면 가볍게 헹궈 물기를 뺍니다.","감자, 마늘, 월계수잎을 넣고 거의 익을 때까지 끓입니다.","사워크라우트, 익힌 강낭콩, 작게 썬 돼지고기를 넣습니다.","걸쭉하고 맛이 어우러질 때까지 끓인 뒤 월계수잎을 빼고 간합니다."]],es:["Jota (guiso esloveno de judías y chucrut)",["Enjuaga el chucrut si está muy salado.","Cuece patata con ajo y laurel hasta casi tierna.","Añade chucrut, alubias cocidas y cerdo en trozos.","Cuece hasta espesar, retira el laurel y sazona."]],ja:["ヨタ（スロベニア風豆とザワークラウトの煮込み）",["ザワークラウトが塩辛ければ軽く洗います。","じゃがいも、にんにく、ローリエをほぼ柔らかくなるまで煮ます。","ザワークラウト、いんげん豆、豚肉を加えます。","とろみが出るまで煮てローリエを除き、味を調えます。"]],zh:["约塔（斯洛文尼亚豆子酸菜炖汤）",["酸菜过咸时稍微冲洗并沥干。","土豆与大蒜、月桂叶煮至近熟。","加入酸菜、熟芸豆和小块猪肉。","小火煮至浓稠融合，取出月桂叶并调味。"]]},
"struklji":{ko:["슈트루클리(슬로베니아식 커드치즈 롤 만두)",["밀가루, 달걀, 물로 부드러운 반죽을 만들어 덮어 둡니다.","반죽을 얇게 밀고 사워크림을 섞은 치즈를 펴 바릅니다.","단단히 말아 감싼 뒤 속까지 익도록 끓입니다.","썰어서 버터에 볶은 빵가루를 올립니다."]],es:["Štruklji (rollos eslovenos rellenos de queso)",["Haz una masa flexible con harina, huevo y agua y déjala reposar.","Estírala fina y unta queso mezclado con crema agria.","Enrolla, envuelve y cuece hasta que la masa esté hecha.","Corta y termina con pan rallado tostado en mantequilla."]],ja:["シュトゥルクリ（スロベニア風カッテージチーズ巻き団子）",["小麦粉、卵、水で柔らかな生地を作り休ませます。","薄く伸ばし、サワークリームを混ぜたチーズを塗ります。","しっかり巻いて包み、中まで火が通るまでゆでます。","切り分け、バターで炒めたパン粉をかけます。"]],zh:["斯洛文尼亚奶酪卷饺",["面粉、鸡蛋和水揉成柔软面团并醒发。","擀薄，铺上拌有酸奶油的奶酪。","紧卷包好，煮至面皮熟透。","切片，撒上黄油炒香的面包屑。"]]},
"adjarian-khachapuri":{ko:["아자룰리 하차푸리(조지아식 배 모양 치즈빵)",["밀가루, 이스트, 따뜻한 우유, 소금으로 반죽해 발효합니다.","반죽을 가장자리가 높은 배 모양으로 만들고 치즈를 채웁니다.","껍질이 노릇하고 치즈가 끓을 때까지 굽습니다.","마지막에 달걀과 버터를 넣고 흰자가 살짝 굳을 만큼만 굽습니다."]],es:["Jachapuri adjaruli (pan georgiano en forma de barca con queso)",["Amasa harina, levadura, leche tibia y sal y deja levar.","Forma una barca con bordes altos y rellena de queso.","Hornea hasta dorar la corteza y burbujear el queso.","Añade huevo y mantequilla al final y cuaja ligeramente la clara."]],ja:["アジャルリ・ハチャプリ（ジョージア風舟形チーズパン）",["小麦粉、酵母、温かい牛乳、塩をこねて発酵させます。","縁を高くした舟形にし、チーズを詰めます。","生地が色づきチーズが沸くまで焼きます。","仕上げに卵とバターを加え、白身が軽く固まるまで焼きます。"]],zh:["阿扎尔哈恰普里（格鲁吉亚船形奶酪面包）",["面粉、酵母、温牛奶和盐揉匀发酵。","整成高边船形并填入奶酪。","烤至外壳金黄、奶酪冒泡。","最后加入鸡蛋和黄油，只烤至蛋白微凝。"]]},
"lobio":{ko:["로비오(조지아식 강낭콩·호두 스튜)",["양파를 천천히 부드럽게 볶고 마늘을 넣습니다.","강낭콩과 삶은 물을 조금 넣고 일부를 으깹니다.","으깬 호두, 고수, 석류 몰라세스를 소량 섞습니다.","걸쭉해질 때까지 끓인 뒤 소금과 산미를 조절합니다."]],es:["Lobio (guiso georgiano de alubias y nueces)",["Pocha la cebolla y añade el ajo.","Añade alubias con un poco de líquido y aplasta una parte.","Incorpora nueces, cilantro y melaza de granada.","Cuece hasta espesar y ajusta sal y acidez."]],ja:["ロビオ（ジョージア風いんげん豆とくるみの煮込み）",["玉ねぎをゆっくり炒め、にんにくを加えます。","いんげん豆と煮汁を加え、一部をつぶします。","砕いたくるみ、パクチー、ざくろモラセスを混ぜます。","とろみが出るまで煮て塩味と酸味を調えます。"]],zh:["洛比奥（格鲁吉亚芸豆核桃炖菜）",["洋葱慢炒至软，加入大蒜。","加入芸豆和少量豆汤，压碎一部分。","拌入碎核桃、香菜和少量石榴糖蜜。","炖至浓稠，调整咸味和酸味。"]]},
"ceebu-jen":{ko:["체부 젠(세네갈식 생선·채소밥)",["생선에 간을 하고 넓은 냄비에서 겉면을 살짝 굽습니다.","토마토와 향신 재료를 볶고 물, 양배추, 당근, 카사바를 넣습니다.","익은 생선과 채소를 건지고 양념된 국물을 남깁니다.","그 국물에 쌀을 익혀 흡수시킨 뒤 생선과 채소를 곁들입니다."]],es:["Ceebu jën (arroz senegalés con pescado y verduras)",["Sazona y dora ligeramente el pescado.","Cuece tomate con aromáticos y añade agua y verduras.","Retira el pescado y las verduras tiernas, reservando el caldo.","Cuece el arroz en ese caldo y sirve todo junto."]],ja:["チェブジェン（セネガル風魚と野菜の炊き込みご飯）",["魚に味をつけ、鍋で表面を軽く焼きます。","トマトと香味野菜を炒め、水、キャベツ、にんじん、キャッサバを加えます。","柔らかくなった魚と野菜を取り出し、煮汁を残します。","その煮汁で米を炊き、魚と野菜を添えます。"]],zh:["塞内加尔鱼蔬饭",["鱼调味后在宽锅中略煎。","番茄与香料炒香，加水、卷心菜、胡萝卜和木薯。","捞出熟鱼和蔬菜，保留调味汤汁。","用汤汁煮饭至吸收，搭配鱼和蔬菜。"]]},
"poulet-yassa":{ko:["풀레 야사(세네갈식 레몬·양파 닭요리)",["닭고기를 얇게 썬 양파, 레몬, 머스터드, 소금, 후추에 재웁니다.","닭고기를 건져 기름을 살짝 두른 팬에서 노릇하게 굽습니다.","재운 양파를 천천히 익히고 양념물과 닭고기를 넣습니다.","부드러워질 때까지 졸여 밥 위에 레몬 양파 소스를 얹습니다."]],es:["Poulet yassa (pollo senegalés al limón y cebolla)",["Marina el pollo con cebolla, limón, mostaza, sal y pimienta.","Retira y dora el pollo con poco aceite.","Cocina lentamente la cebolla y devuelve la marinada y el pollo.","Guisa hasta tierna y sirve la salsa sobre arroz."]],ja:["プレ・ヤッサ（セネガル風レモン玉ねぎチキン）",["鶏肉を玉ねぎ、レモン、マスタード、塩、こしょうで漬けます。","鶏肉を取り出し、少量の油で焼きます。","漬けた玉ねぎをゆっくり炒め、漬け汁と鶏肉を戻します。","柔らかく煮て、レモン玉ねぎソースを米にかけます。"]],zh:["亚萨鸡（塞内加尔柠檬洋葱鸡）",["鸡肉用洋葱、柠檬、芥末、盐和胡椒腌制。","取出鸡肉，用少量油煎至上色。","慢炒腌过的洋葱，加入腌汁和鸡肉。","炖至软嫩，将柠檬洋葱酱浇在米饭上。"]]},
"beef-rendang":{ko:["렌당 다깅(인도네시아식 코코넛 쇠고기 조림)",["양파, 마늘, 생강, 향신료를 곱게 갈아 향긋한 페이스트를 만듭니다.","페이스트를 약불에 볶고 쇠고기를 넣어 고루 묻힙니다.","코코넛밀크를 붓고 뚜껑 없이 약불로 끓입니다.","국물이 줄면 자주 저어 쇠고기가 부드럽고 진한 소스가 달라붙을 때까지 익힙니다."]],es:["Rendang daging (ternera indonesia braseada en coco)",["Tritura cebolla, ajo, jengibre y especias.","Cocina la pasta suavemente y cubre con ella la ternera.","Añade leche de coco y cuece destapado a fuego bajo.","Remueve al reducir hasta que la carne esté tierna y la salsa oscura se adhiera."]],ja:["ルンダン・ダギン（インドネシア風牛肉のココナッツ煮込み）",["玉ねぎ、にんにく、生姜、香辛料をペーストにします。","弱火で炒め、牛肉にまんべんなく絡めます。","ココナッツミルクを加え、ふたをせず弱火で煮ます。","水分が減ったらよく混ぜ、肉が柔らかく濃いソースが絡むまで煮ます。"]],zh:["仁当牛肉（印尼椰奶炖牛肉）",["洋葱、大蒜、生姜和香料打成香料酱。","小火炒香，加入牛肉均匀裹酱。","倒入椰奶，不加盖小火慢炖。","汤汁收浓后勤翻动，炖至牛肉软烂、深色酱汁附着。"]]},
"satay-ayam":{ko:["사테 아얌(인도네시아식 닭꼬치)",["닭고기를 고르게 작게 썰어 간장, 마늘, 라임, 설탕에 재웁니다.","닭 조각 사이를 너무 붙이지 않고 꼬치에 끼웁니다.","센 불에서 돌려가며 겉이 노릇하고 속까지 익도록 굽습니다.","땅콩을 으깨 따뜻한 소스로 만들어 뜨거운 꼬치와 냅니다."]],es:["Sate ayam (brochetas indonesias de pollo)",["Corta y marina el pollo con soja, ajo, lima y azúcar.","Ensarta sin apretar demasiado los trozos.","Asa a fuego fuerte, girando hasta dorar y cocinar por completo.","Tritura cacahuetes en una salsa tibia y sirve con las brochetas."]],ja:["サテ・アヤム（インドネシア風鶏串焼き）",["鶏肉を小さく切り、醤油、にんにく、ライム、砂糖で漬けます。","詰めすぎないよう串に刺します。","強火で返しながら、焼き色がつき中まで火が通るまで焼きます。","ピーナッツを温かいソースにして串焼きに添えます。"]],zh:["沙嗲鸡（印尼鸡肉串）",["鸡肉切成均匀小块，用酱油、大蒜、青柠和糖腌制。","鸡块不要挤得过紧，穿上竹签。","大火翻烤至上色并完全熟透。","花生捣成温热酱汁，搭配热鸡串。"]]},
"pelkie-zirni-ar-speki":{ko:["펠레키에 지르니 아르 스페키(라트비아식 회색완두콩·베이컨)",["말린 완두콩을 미리 불린 뒤 모양이 남게 부드럽게 삶습니다.","베이컨을 깍둑썰기해 기름이 나오고 가장자리가 노릇하게 익힙니다.","양파를 넣어 부드럽게 볶고 물기 뺀 콩과 버터를 섞습니다.","사워크림과 호밀빵을 곁들여 뜨겁게 냅니다."]],es:["Pelēkie zirņi ar speķi (guisantes grises letones con beicon)",["Remoja los guisantes y cuécelos tiernos pero enteros.","Dora el beicon hasta que suelte la grasa.","Añade cebolla, luego mezcla los guisantes y mantequilla.","Sirve caliente con crema agria y pan de centeno."]],ja:["ペーレーキエ・ズィルニ・アル・スペキ（ラトビア風灰色えんどう豆とベーコン）",["乾燥えんどう豆を浸水し、形を残して柔らかく煮ます。","角切りベーコンを脂が出て色づくまで炒めます。","玉ねぎを加え、豆とバターを混ぜます。","サワークリームとライ麦パンを添えます。"]],zh:["拉脱维亚灰豌豆配培根",["干豌豆提前浸泡，煮软但保持完整。","培根切丁，煎至出油并上色。","加入洋葱炒软，再拌入沥干豌豆和黄油。","趁热配酸奶油和黑麦面包。"]]},
"sklandrausis":{ko:["스클란드라우시스(라트비아식 호밀·감자·당근 타르트)",["호밀가루에 따뜻한 물과 버터를 섞어 가장자리가 높은 작은 타르트 틀로 만듭니다.","바닥에 부드러운 감자층을 펴 바릅니다.","달걀과 사워크림을 섞은 달콤한 당근 퓌레를 올립니다.","호밀 껍질이 단단하고 당근 표면이 살짝 갈색이 될 때까지 굽습니다."]],es:["Sklandrausis (tarta letona de centeno, patata y zanahoria)",["Mezcla harina de centeno, agua tibia y mantequilla y forma tartaletas.","Extiende una capa lisa de patata.","Cubre con puré dulce de zanahoria, huevo y crema agria.","Hornea hasta que la base esté firme y la superficie dorada."]],ja:["スクランドラウシス（ラトビア風ライ麦・じゃがいも・にんじんタルト）",["ライ麦粉に温水とバターを混ぜ、縁の高い小さな型にします。","なめらかなじゃがいもの層を敷きます。","卵とサワークリームを混ぜた甘いにんじんピュレを重ねます。","生地が固まり表面が軽く色づくまで焼きます。"]],zh:["斯克兰德劳西斯（拉脱维亚黑麦土豆胡萝卜挞）",["黑麦粉加温水和黄油，压成带高边的小挞壳。","底部铺平滑土豆泥。","覆盖拌鸡蛋和酸奶油的甜胡萝卜泥。","烤至黑麦壳定型、胡萝卜表面微黄。"]]}
});
